struct MonitoredNode {
    telemetry: SharedTelemetry,
    heartbeat_pub: Topic<NodeHeartbeat>,
    status_pub: Topic<Status>,
    resources_pub: Topic<ResourceUsage>,
    start_time: std::time::Instant,
    tick_count: u64,
}

impl Node for MonitoredNode {
    fn name(&self) -> &'static str { "MonitoredNode" }

    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        self.tick_count += 1;

        // Record telemetry metrics
        {
            let mut tm = self.telemetry.lock().unwrap();
            tm.counter("node_ticks", self.tick_count);
            tm.gauge("uptime_secs", self.start_time.elapsed().as_secs_f64());

            // Export periodically
            if tm.should_export() {
                if let Err(e) = tm.export() {
                    log::warn!("Telemetry export failed: {}", e);
                }
            }
        }

        // Publish heartbeat
        let mut heartbeat = NodeHeartbeat::new(NodeState::Running, HealthStatus::Healthy);
        heartbeat.tick_count = self.tick_count;
        heartbeat.target_rate = 100;
        heartbeat.actual_rate = self.calculate_rate();
        self.heartbeat_pub.send(heartbeat, &mut ctx).ok();

        // Publish resource usage
        let resources = self.get_resource_usage();
        self.resources_pub.send(resources, &mut ctx).ok();

        // Publish status on significant events
        if self.tick_count % 1000 == 0 {
            let status = Status::ok(&format!("Completed {} ticks", self.tick_count))
                .with_component("MonitoredNode");
            self.status_pub.send(status, &mut ctx).ok();
        }
    }
}

impl MonitoredNode {
    fn calculate_rate(&self) -> u32 {
        // Calculate actual tick rate
        let elapsed = self.start_time.elapsed().as_secs_f64();
        if elapsed > 0.0 {
            (self.tick_count as f64 / elapsed) as u32
        } else {
            0
        }
    }

    fn get_resource_usage(&self) -> ResourceUsage {
        let mut resources = ResourceUsage::new();
        // Populate with actual system metrics
        resources.cpu_percent = 25.0;
        resources.memory_percent = 40.0;
        resources.temperature = 45.0;
        resources
    }
}

use horus::prelude::*;
use horus::prelude::*; // Provides CmdVel;

#[derive(Debug, Clone, Copy, PartialEq)]
enum RobotState {
    Idle,
    Moving,
    ObstacleDetected,
    Rotating,
    Escaped,
}

struct StateMachineNode {
    state: RobotState,
    obstacle_sub: Topic<bool>,
    cmd_pub: Topic<CmdVel>,
    rotation_counter: u32,
}

impl StateMachineNode {
    fn new() -> Result<Self> {
        Ok(Self {
            state: RobotState::Idle,
            obstacle_sub: Topic::new("obstacle_detected")?,
            cmd_pub: Topic::new("cmd_vel")?,
            rotation_counter: 0,
        })
    }
}

impl Node for StateMachineNode {
    fn name(&self) -> &'static str { "StateMachineNode" }

    fn init(&mut self, ctx: &mut NodeInfo) -> Result<()> {
        ctx.log_info("State machine initialized - starting in IDLE state");
        Ok(())
    }

    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        // Check for obstacles
        let obstacle = self.obstacle_sub.recv(&mut ctx).unwrap_or(false);

        // Store previous state for logging
        let prev_state = self.state;

        // State machine logic
        self.state = match self.state {
            RobotState::Idle => {
                if !obstacle {
                    RobotState::Moving
                } else {
                    RobotState::Idle
                }
            }

            RobotState::Moving => {
                if obstacle {
                    self.cmd_pub.send(CmdVel::zero(), &mut ctx).ok();  // Stop
                    RobotState::ObstacleDetected
                } else {
                    self.cmd_pub.send(CmdVel::new(1.0, 0.0), &mut ctx).ok();  // Forward
                    RobotState::Moving
                }
            }

            RobotState::ObstacleDetected => {
                self.rotation_counter = 0;
                RobotState::Rotating
            }

            RobotState::Rotating => {
                self.cmd_pub.send(CmdVel::new(0.0, 0.5), &mut ctx).ok();  // Rotate
                self.rotation_counter += 1;

                if self.rotation_counter > 50 {
                    RobotState::Escaped
                } else {
                    RobotState::Rotating
                }
            }

            RobotState::Escaped => {
                RobotState::Moving  // Resume moving
            }
        };

        // Log state transitions
        if self.state != prev_state {
            if let Some(ref mut c) = ctx {
                c.log_info(&format!(
                    "State transition: {:?} -> {:?}",
                    prev_state, self.state
                ));
            }
        }
    }

    fn shutdown(&mut self, ctx: &mut NodeInfo) -> Result<()> {
        // Ensure robot is stopped
        self.cmd_pub.send(CmdVel::zero(), &mut None).ok();
        ctx.log_info("State machine shutdown");
        Ok(())
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();
    scheduler.add(Box::new(StateMachineNode::new()?), 0, Some(true));
    scheduler.run()?;
    Ok(())
}

