enum RobotState {
    Idle,
    Moving,
    Stopped,
}

struct RobotController {
    state: RobotState,
    cmd_sub: Topic<CmdVel>,
}

impl Node for RobotController {
    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        match self.state {
            RobotState::Idle => {
                if let Some(cmd) = self.cmd_sub.recv(&mut ctx) {
                    self.state = RobotState::Moving;
                }
            }
            RobotState::Moving => {
                // Execute movement
                if self.is_done() {
                    self.state = RobotState::Stopped;
                }
            }
            RobotState::Stopped => {
                self.state = RobotState::Idle;
            }
        }
    }
}

struct Synchronizer {
    topic_a: Topic<f32>,
    topic_b: Topic<f32>,
    last_a: Option<f32>,
    last_b: Option<f32>,
}

impl Node for Synchronizer {
    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        // Update cached values
        if let Some(a) = self.topic_a.recv(&mut ctx) {
            self.last_a = Some(a);
        }
        if let Some(b) = self.topic_b.recv(&mut ctx) {
            self.last_b = Some(b);
        }

        // Process when both available
        if let (Some(a), Some(b)) = (self.last_a, self.last_b) {
            self.process(a, b);
        }
    }
}

