use horus::prelude::*;

// Define messages in one line each!
message!(TempReading = (f32, u64));  // (celsius, timestamp)
message!(Alert = (bool, f32));       // (is_critical, threshold)

// Sensor node
struct TempSensor {
    publisher: Topic<TempReading>,
    reading: f32,
}

impl TempSensor {
    fn new() -> Result<Self> {
        Ok(Self {
            publisher: Topic::new("sensors.temperature")?,
            reading: 20.0,
        })
    }
}

impl Node for TempSensor {
    fn name(&self) -> &'static str { "temp_sensor" }

    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;

        let reading = TempReading(self.reading, now);
        self.publisher.send(reading, &mut ctx).ok();

        self.reading += 0.1;  // Simulate change
    }
}

// Alert node
struct AlertMonitor {
    subscriber: Topic<TempReading>,
    alert_pub: Topic<Alert>,
    threshold: f32,
}

impl AlertMonitor {
    fn new() -> Result<Self> {
        Ok(Self {
            subscriber: Topic::new("sensors.temperature")?,
            alert_pub: Topic::new("alerts.temperature")?,
            threshold: 30.0,
        })
    }
}

impl Node for AlertMonitor {
    fn name(&self) -> &'static str { "alert_monitor" }

    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        if let Some(TempReading(temp, _)) = self.subscriber.recv(&mut ctx) {
            if temp > self.threshold {
                let alert = Alert(true, temp);
                self.alert_pub.send(alert, &mut ctx).ok();
                println!("  High temperature: {:.1}°C", temp);
            }
        }
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new().name("temp_monitor");

    scheduler.add(Box::new(TempSensor::new()?), 0, Some(true));
    scheduler.add(Box::new(AlertMonitor::new()?), 1, Some(true));

    scheduler.run()
}

