}

impl ModeController {
    pub fn new() -> Result<Self> {
        let fsm = StateMachineBuilder::<RobotModeContext>::new("mode_ctrl")
            .initial_state("idle").build()
            .state("active").build()
            .transition("idle", "active").on_event("start").build()
            .transition("active", "idle").on_event("stop").build()
            .build()?;

