}

impl TFLiteClassifierNode {
    pub fn new(model_path: &str, labels_path: &str) -> Result<Self> {
        // Load TFLite model
        let model = FlatBufferModel::build_from_file(model_path)
            .map_err(|e| Error::Config(format!("TFLite error: {}", e)))?;

        let resolver = BuiltinOpResolver::default();
        let builder = InterpreterBuilder::new(model, resolver)
            .map_err(|e| Error::Config(format!("Builder error: {}", e)))?;

        let mut interpreter = builder.build()
            .map_err(|e| Error::Config(format!("Interpreter error: {}", e)))?;

        interpreter.allocate_tensors()
            .map_err(|e| Error::Config(format!("Allocation error: {}", e)))?;

        // Load class labels
        let labels = std::fs::read_to_string(labels_path)
            .map_err(|e| Error::Config(format!("Labels error: {}", e)))?
            .lines()
            .map(String::from)
            .collect();

        Ok(Self {
            camera_sub: Topic::new("camera.raw")?,
            class_pub: Topic::new("vision.classification")?,
            interpreter,
            labels,
        })
    }

    fn classify(&mut self, img_data: &[u8]) -> Option<String> {
        // Preprocess and set input tensor
        let input_tensor = self.interpreter.input(0)?;
        // ... preprocessing code ...

        // Run inference
        self.interpreter.invoke().ok()?;

        // Get output
        let output_tensor = self.interpreter.output(0)?;
        let scores = output_tensor.data::<f32>();

        // Find top class
        let (max_idx, max_score) = scores
            .iter()
            .enumerate()
            .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap())?;

        Some(format!("{}: {:.2}%", self.labels[max_idx], max_score * 100.0))
    }
}

