pub struct LLMCommandNode {
    text_sub: Topic<String>,  // Natural language commands
    cmd_pub: Topic<String>,   // Structured robot commands
    context: LlamaContext,
}

impl LLMCommandNode {
    pub fn new(model_path: &str) -> Result<Self> {
        // Load LLaMA model (Llama 2, Mistral, Phi, etc.)
        let params = LlamaParams::default();
        let model = LlamaModel::load_from_file(model_path, params)
            .map_err(|e| Error::Config(format!("Failed to load LLM: {}", e)))?;

        let context = model.create_context(LlamaParams::default())
            .map_err(|e| Error::Config(format!("Context error: {}", e)))?;

        Ok(Self {
            text_sub: Topic::new("speech.text")?,
            cmd_pub: Topic::new("robot.commands")?,
            context,
        })
    }

    fn generate_command(&mut self, user_input: &str) -> Option<String> {
        let prompt = format!(
            "You are a robot command interpreter. Convert natural language to JSON commands.\n\
            User: {}\n\
            Command (JSON): ",
            user_input
        );

        // Generate response
        let output = self.context.predict(
            prompt,
            64,  // max tokens
            true,  // echo prompt
            |token| {
                // Token callback
                print!("{}", token);
                true
            }
        ).ok()?;

        // Extract JSON command
        Some(output.trim().to_string())
    }
}

impl Node for LLMCommandNode {
    fn name(&self) -> &'static str { "LLMCommandNode" }

    fn tick(&mut self, mut ctx: Option<&mut NodeInfo>) {
        if let Some(text) = self.text_sub.recv(&mut ctx) {
