import numpy as np

class CameraNode(Node):
    def __init__(self):
        self.output = Topic("camera.raw")

    def name(self):
        return "CameraNode"

    def tick(self):
        # Simulate camera frame
        frame = np.random.randint(0, 255, (480, 640, 3), dtype=np.uint8)
        self.output.send(frame)


class DetectorNode(Node):
    def __init__(self):
        self.camera = Topic("camera.raw")
        self.output = Topic("detections")
        self.detector = ObjectDetector()
        self.detector.load_model()
        self.monitor = PerformanceMonitor()

    def name(self):
        return "DetectorNode"

    def tick(self):
        if frame := self.camera.recv():
            result, latency = self.detector.run_inference(frame)
            self.monitor.record(latency)
            self.output.send(result)

            # Print stats every 100 frames
            if self.monitor.get_stats()["samples"] % 100 == 0:
                self.monitor.print_stats()


def main():
    scheduler = Scheduler()
    scheduler.add(CameraNode(), priority=0)
    scheduler.add(DetectorNode(), priority=1)
    scheduler.run()

if __name__ == "__main__":
    main()

