// Stage 1: Data acquisition
struct SensorNode {
    raw_pub: Topic<f32>,
    counter: f32,
}

impl SensorNode {
    fn new() -> Result<Self> {
        Ok(Self {
            raw_pub: Topic::new("raw_data")?,
